export type NivelGobiernoTramite = 'municipal' | 'estatal' | 'federal';

export type EtapaTramite = 'construccion' | 'operacion' | 'pre_inversion';

export interface TramiteRequisitoItem {
  id: string;
  nombre: string;
  descripcion?: string;
  obligatorio: boolean;
  formatoAceptado?: string;
}

export interface TramitePestana {
  id: string;
  titulo: string;
  subtitulo?: string;
  icono?: string;
}

export interface TramiteCatalogoItem {
  id: string;
  claveOficial: string;
  nombre: string;
  descripcion: string;
  dependencia: string;
  nivelGobierno: NivelGobiernoTramite;
  municipioNombre: string;
  municipioId: number | null;
  escudoUrl: string;
  etapa: EtapaTramite;
  vigenciaDias: number;
  modalidad: string[];
  pestanas: TramitePestana[];
  requisitos: TramiteRequisitoItem[];
}

export interface TramiteSolicitudData {
  tramiteId: string;
  municipioId: number | null;
  municipioNombre: string;
  personalidad: 'fisica' | 'moral';
  nombreSolicitante: string;
  razonSocial?: string;
  rfc: string;
  representanteLegal?: string;
  correo: string;
  telefono: string;
  calle: string;
  numeroExterior: string;
  numeroInterior?: string;
  colonia: string;
  codigoPostal: string;
  claveCatastral: string;
  superficieTotalM2: number | null;
  superficieConstruidaM2: number | null;
  latitud: number | null;
  longitud: number | null;
  altitud: number | null;
  tipoTramiteEspecifico?: string;
  descripcionProyecto?: string;
  actividadPrincipal?: string;
  vidaUtilAnos?: number | null;
  maquinariaEquipo?: string;
  combustiblesUtilizados?: string;
  emisionesAtmosfera?: string;
  manejoResiduos?: string;
  medidasMitigacion?: string;
  colindanciaNorte?: string;
  colindanciaSur?: string;
  colindanciaEste?: string;
  colindanciaOeste?: string;
  tipoGeneradorRme?: 'industrial' | 'comercial' | '';
  documentosAdjuntos: Record<string, { file: File | null; id: number | null; name: string }>;
}

