    codigoPostal: '',
    claveCatastral: '',
    superficieTotalM2: null,
    superficieConstruidaM2: null,
    latitud: null,
    longitud: null,
    altitud: null,
    tipoTramiteEspecifico: '',
    descripcionProyecto: '',
    actividadPrincipal: '',
    vidaUtilAnos: null,
    maquinariaEquipo: '',
    combustiblesUtilizados: '',
    emisionesAtmosfera: '',
    manejoResiduos: '',
    medidasMitigacion: '',
    colindanciaNorte: '',
