import { Component, computed, input } from '@angular/core';

@Component({
  selector: 'app-tramite-progress-bar',
  templateUrl: './tramite-progress-bar.component.html',
  styleUrl: './tramite-progress-bar.component.scss',
  host: {
    class: 'd-block w-100',
  },
})
export class TramiteProgressBarComponent {
  readonly completed = input<number>(0);
  readonly total = input<number>(0);
  readonly totalRequired = input<number>(0);
  readonly label = input<string>('Progreso de campos y documentos obligatorios');
  readonly showCount = input<boolean>(true);
  readonly showPercentage = input<boolean>(true);
  readonly effectiveTotal = computed(() => this.totalRequired() || this.total());
  readonly percentage = computed(() => {
    const total = this.effectiveTotal();
    if (total <= 0) return 0;
    const completed = this.completed();
    return Math.min(100, Math.max(0, Math.round((completed / total) * 100)));
  });

  readonly isComplete = computed(() => this.percentage() === 100 && this.effectiveTotal() > 0);
}
